WITH base AS (SELECT *, SORT_ARRAY(tags) AS sorted_tags FROM products WHERE stock_qty > 346), launch_month_summary AS (SELECT DATE_TRUNC('MONTH', launch_date) AS launch_month, ROUND((100 * SUM(CASE WHEN category = 'Grocery' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_grocery, COUNT(*) AS cnt FROM base GROUP BY DATE_TRUNC('MONTH', launch_date)) SELECT * FROM launch_month_summary WHERE pct_grocery > 55;
